/**
 * extract-pack-store — deterministic faction-pack PDF → out-of-repo raw-text store
 * for a pack's stratagems and enhancements, capturing the FULL card prose
 * (WHEN/TARGET/EFFECT/RESTRICTIONS for stratagems; the rule text for
 * enhancements).
 *
 * Extraction uses the COORDINATE foundation (extractPackCards →
 * detachmentSegments/findAnchors/captureBody), NOT linearized `pdftotext -`.
 * Cards are located inside their detachment's coordinate region, so the
 * detachment association is reliable and the 2-column card layout never
 * interleaves. Requires poppler's pdftotext (`-bbox-layout`); XPDF fails loudly.
 *
 * Match to canonical core ability_id via data/core entities (name-slug, prefer
 * same detachment), so store keys line up with the app's lookup.
 *
 * IP posture: prose lands ONLY in the out-of-repo store (default
 * ../40kdc-abilities), never in this repo.
 *
 * Precedence: writes with source.kind "pdf" (11e, verbatim) and OVERWRITES any
 * game-datacards 10e entry for the same id (pdf supersedes 10e); never touches a
 * different existing pdf entry.
 *
 * Usage:
 *   npx tsx tools/src/extract-pack-store.ts <pdf> --faction <id> [--store <dir>] [--dry-run]
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { fileURLToPath } from "node:url";
import { slug, titleCase } from "./pack-blocks.js";
import { extractPackCards } from "./author-input-pack.js";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const REPO = resolve(__dirname, "../..");
const args = process.argv.slice(2);
const flag = (n: string): string | undefined => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };
const PDF = args.find((a, i) => !a.startsWith("--") && !["--faction", "--store"].includes(args[i - 1]));
const FACTION = flag("--faction");
const STORE_ROOT = resolve(REPO, flag("--store") ?? "../40kdc-abilities");
const DRY = args.includes("--dry-run");
if (!PDF || !FACTION) { console.error("usage: extract-pack-store <pdf> --faction <id> [--store <dir>] [--dry-run]"); process.exit(2); }

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any;
const readJSON = (p: string): Json => JSON.parse(readFileSync(p, "utf-8"));

// split a stratagem body into structured sections from its WHEN/TARGET/EFFECT/RESTRICTIONS labels.
const sectionsOf = (blob: string): Json => {
  const grab = (label: RegExp, nexts: RegExp[]): string => {
    const mm = blob.match(label); if (!mm) return "";
    const rest = blob.slice(mm.index! + mm[0].length); let end = rest.length;
    for (const n of nexts) { const nm = rest.match(n); if (nm && nm.index! < end) end = nm.index!; }
    return rest.slice(0, end).replace(/\s+/g, " ").trim();
  };
  const o: Json = {
    when: grab(/WHEN:/i, [/TARGET:/i, /EFFECT:/i, /RESTRICTIONS:/i]),
    target: grab(/TARGET:/i, [/EFFECT:/i, /RESTRICTIONS:/i]),
    effect: grab(/EFFECT:/i, [/RESTRICTIONS:/i]),
  };
  const r = grab(/RESTRICTIONS:/i, []); if (r) o.restrictions = r;
  return o;
};
// enhancement rule text: drop a leading flavour sentence (keep from the first mechanical opening).
const RULE_START = /(Friendly|Models? |Each time|Once per|While |Add \d|Subtract|Improve|In your|At the (start|end)|You can|This (unit|model|army)|Designate|Whenever|If (a|an|your|you|this)|Units? |When |[A-Z]+ (unit|model)s? only|Ranged|Melee|Select |Re-?roll)/;
const stripFlavour = (body: string): string => { const m = body.match(RULE_START); return (m && m.index! > 0 ? body.slice(m.index!) : body).trim(); };

// --- pull stratagem + enhancement cards from the pack (coordinate-based) ---
const cards = extractPackCards(resolve(REPO, PDF));

// --- core entities for canonical-id matching ---
const coreStrat: Json[] = existsSync(join(REPO, "data/core", FACTION, "stratagems.json")) ? readJSON(join(REPO, "data/core", FACTION, "stratagems.json")) : [];
const coreEnh: Json[] = existsSync(join(REPO, "data/core", FACTION, "enhancements.json")) ? readJSON(join(REPO, "data/core", FACTION, "enhancements.json")) : [];
const normEnh = (s: string): string => slug(String(s).replace(/\s*upgrade\s*$/i, ""));
const stratKey = (name: string, det: string): string | null => {
  const ns = slug(name);
  const hit = coreStrat.find((c) => slug(c.name) === ns && c.detachment_id === det) ?? coreStrat.find((c) => slug(c.name) === ns);
  return hit ? (hit.ability_id ?? hit.id) : null;
};
const enhKey = (name: string, det: string): string | null => {
  const ns = normEnh(name);
  const hit = coreEnh.find((c) => normEnh(c.name) === ns && c.detachment_id === det) ?? coreEnh.find((c) => normEnh(c.name) === ns);
  return hit ? (hit.ability_id ?? hit.id) : null;
};

// --- write to store (fill-only; pdf supersedes game-datacards) ---
const storePath = join(STORE_ROOT, `${FACTION}.json`);
const store: Json[] = existsSync(storePath) ? readJSON(storePath) : [];
const byId = new Map(store.map((e) => [e.ability_id, e]));
const GV = { edition: "11th", dataslate: "pre-launch-provisional" };
const ref = PDF.split(/[\\/]/).pop();
let written = 0, supersededGdc = 0, unmatched = 0; const unmatchedNames: string[] = [];

for (const c of cards) {
  if (c.kind === "detachment") continue; // detachment rules are handled by extract-detachment-rules
  const isStrat = c.kind === "stratagem";
  const key = isStrat ? stratKey(c.name, c.detachment_id) : enhKey(c.name, c.detachment_id);
  if (!key) { unmatched++; unmatchedNames.push(`${c.name} (${c.detachment_id})`); continue; }
  const fields = isStrat ? sectionsOf(c.body) : { raw_text: stripFlavour(c.body) };
  if (isStrat && !(fields as Json).when && !(fields as Json).effect) continue; // unparseable stratagem body
  if (!isStrat && !(fields as Json).raw_text) continue;
  const existing = byId.get(key);
  if (existing) {
    if (existing.source?.kind === "game-datacards") {
      delete existing.raw_text; delete existing.when; delete existing.target; delete existing.effect; delete existing.restrictions;
      Object.assign(existing, fields);
      existing.source = { kind: "pdf", ref, edition: "11e" };
      supersededGdc++; written++;
    }
    // existing pdf entry: leave it (already authoritative)
  } else {
    const entry = {
      ability_id: key, name: titleCase(c.name), faction_id: FACTION, unit_ids: [],
      ability_type: isStrat ? "stratagem" : "enhancement", game_version: GV,
      source: { kind: "pdf", ref, edition: "11e" }, ...fields,
    };
    store.push(entry); byId.set(key, entry); written++;
  }
}

console.log(`${FACTION}: cards=${cards.length} written=${written} (superseded gdc ${supersededGdc}) unmatched=${unmatched}`);
if (unmatchedNames.length) console.log("  unmatched:", unmatchedNames.slice(0, 12).join(" | "));
if (written && !DRY) {
  if (!existsSync(STORE_ROOT)) mkdirSync(STORE_ROOT, { recursive: true });
  writeFileSync(storePath, JSON.stringify(store, null, 2) + "\n");
}
if (DRY) console.log("  (dry-run — nothing written)");
